import AppKit

/// Observes new clipboard ownership only; launching or resuming never imports old content.
@MainActor
final class ClipboardMonitor {
    static let sourceType = NSPasteboard.PasteboardType("org.nspasteboard.source")
    static let sourceIdentifier = "com.contextbasket.mac"
    // Clipboard producers use these markers to exclude content from history.
    // https://nspasteboard.org/
    private static let ignoredTypes: Set<NSPasteboard.PasteboardType> = Set([
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
        "Pasteboard generator type"
    ].map { NSPasteboard.PasteboardType($0) })

    private weak var store: BasketStore?
    private let pasteboard: NSPasteboard
    private var lastChangeCount: Int
    private var timer: Timer?
    private var isEnabled = false

    init(store: BasketStore, pasteboard: NSPasteboard = .general) {
        self.store = store
        self.pasteboard = pasteboard
        lastChangeCount = pasteboard.changeCount
    }

    deinit { timer?.invalidate() }

    func setEnabled(_ enabled: Bool) {
        guard enabled != isEnabled else { return }
        isEnabled = enabled
        timer?.invalidate()
        timer = nil
        lastChangeCount = pasteboard.changeCount
        guard enabled else { return }
        let timer = Timer(timeInterval: 0.4, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { _ = self?.poll() }
        }
        timer.tolerance = 0.1
        self.timer = timer
        RunLoop.main.add(timer, forMode: .common)
    }

    @discardableResult
    func poll() -> [Task<Void, Never>] {
        guard isEnabled, let store else { return [] }
        let changeCount = pasteboard.changeCount
        guard changeCount != lastChangeCount else { return [] }
        lastChangeCount = changeCount
        if #available(macOS 15.4, *), pasteboard.accessBehavior == .alwaysDeny {
            store.errorMessage = "macOS 已阻止剪贴板访问。请在系统设置中允许 context basket 读取剪贴板，再复制一次。"
            return []
        }
        let types = Set(pasteboard.types ?? [])
        guard types.isDisjoint(with: Self.ignoredTypes),
              pasteboard.string(forType: Self.sourceType) != Self.sourceIdentifier else { return [] }
        let incoming = DropReader.read(pasteboard)
        // A producer can replace its data while it is being read; retry the new change next tick.
        guard pasteboard.changeCount == changeCount, !incoming.isEmpty else { return [] }
        return store.add(incoming, mode: .copy)
    }
}
